# trex-test -- prepare the domain controller (dc01, crowd.axr.lab) for the
# crowd's SMB sessions: register the two file servers the sessions name.
#
# The crowd's SMB templates (personas/trex-crowd-client.yaml, generated by
# scripts/gen-smb-sessions.py) connect to \\fs01.crowd.axr.lab\shared and
# \\fs02.crowd.axr.lab\shared and log in as CROWD\alice and CROWD\bob. The
# users come from te.yaml's `identity:` block (the engine creates them); this
# script adds the A records, so the names on the wire resolve in the domain's
# own DNS to the addresses trex-server answers for:
#     fs01.crowd.axr.lab -> 10.250.2.1
#     fs02.crowd.axr.lab -> 10.250.2.2
#
# Delivered as `install: [{script: ...}]` (OP-APP-030 run-script), which on a
# Windows host runs `powershell -NoProfile -ExecutionPolicy Bypass -File`. It
# gates on this app's provision-app (the AD DS promotion), not on the DNS
# Server service being up, so it polls for the zone first (svc-engines'
# prepare-dc.ps1 found the same race). PLAIN POWERSHELL, no shebang.
#
# FAIL-LOUD: each record is resolved back through the DC's own DNS server.
$ErrorActionPreference = 'Stop'

$zone = 'crowd.axr.lab'
$records = [ordered]@{ 'fs01' = '10.250.2.1'; 'fs02' = '10.250.2.2' }

# 1. Wait for the DNS Server service and the AD-integrated zone.
$deadline = (Get-Date).AddSeconds(600)
$ready = $false
while (-not $ready -and (Get-Date) -lt $deadline) {
    try {
        $svc = Get-Service -Name DNS -ErrorAction Stop
        if ($svc.Status -ne 'Running') { Start-Service -Name DNS -ErrorAction SilentlyContinue }
        Get-DnsServerZone -Name $zone -ErrorAction Stop | Out-Null
        $ready = $true
    } catch {
        Start-Sleep -Seconds 5
    }
}
if (-not $ready) {
    throw "prepare-dc: zone $zone was not served within 600s"
}

# 2. Add the records. Idempotent: an existing record with another address is
#    replaced, one with the right address is left alone.
foreach ($name in $records.Keys) {
    $ip = $records[$name]
    $have = Get-DnsServerResourceRecord -ZoneName $zone -Name $name -RRType A -ErrorAction SilentlyContinue
    if ($have -and ($have.RecordData.IPv4Address.IPAddressToString -ne $ip)) {
        $have | Remove-DnsServerResourceRecord -ZoneName $zone -Force
        $have = $null
    }
    if (-not $have) {
        Add-DnsServerResourceRecordA -ZoneName $zone -Name $name -IPv4Address $ip
    }
}

# 3. Read back through the DC's own DNS server.
foreach ($name in $records.Keys) {
    $fqdn = "$name.$zone"
    $got = (Resolve-DnsName -Name $fqdn -Type A -Server 127.0.0.1 -DnsOnly -ErrorAction Stop |
            Where-Object { $_.Type -eq 'A' } | Select-Object -First 1).IPAddress
    if ($got -ne $records[$name]) {
        throw "prepare-dc: $fqdn resolves to '$got', expected $($records[$name])"
    }
}
Write-Output "AXR_TREX_DC_OK fs01 -> 10.250.2.1, fs02 -> 10.250.2.2 in $zone"
